<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { retrieveImageTransfer, retrieveTransfer } from '../services/transfers'
const p=defineProps<{id:string}>(),r=useRouter(),text=ref(''),url=ref(''),expires=ref(''),copied=ref(false),loading=ref(true); async function copy(){try{await navigator.clipboard.writeText(text.value);copied.value=true}catch{copied.value=false}} onMounted(async()=>{try{try{const t=await retrieveTransfer(p.id);text.value=t.content;expires.value=new Intl.DateTimeFormat('en',{hour:'2-digit',minute:'2-digit'}).format(new Date(t.expiresAt))}catch{const t=await retrieveImageTransfer(p.id);url.value=t.imageUrl;expires.value=new Intl.DateTimeFormat('en',{hour:'2-digit',minute:'2-digit'}).format(new Date(t.expiresAt))}}catch{await r.replace('/expired')}finally{loading.value=false}})
</script><template><section class="result-minimal"><p v-if="loading">Loading…</p><template v-else><h1>Received.</h1><article class="received-details"><img v-if="url" :src="url" class="result-image" alt="Received image"><pre v-else>{{ text }}</pre><div class="result-meta"><span>Expires at {{ expires }}</span><a v-if="url" class="quiet-action" :href="url" download>Save image</a><button v-else class="quiet-action" @click="copy">{{ copied?'Copied':'Copy' }}</button></div></article></template></section></template>
